/* Review-only prototype. All data are illustrative; no app or DAW APIs are called. */
const screen = new URLSearchParams(location.search).get('screen') || 'production';
const app = document.querySelector('#app');
const labels = {production:'Production',script:'Script',booth:'Booth',proof:'Proof',master:'Master & QC',series:'Story Bible',companion:'Companion',settings:'Settings',import:'Import review',pickups:'Pickups',project:'Projects',states:'Interaction states'};
const badge=(s,c='')=>`<span class="badge ${c}">${s}</span>`;
const btn=(s,c='',action='')=>`<button class="${c}" ${action?`data-action="${action}"`:''}>${s}</button>`;
const wave=(n=95)=>`<div class="wave" aria-label="Illustrative audio waveform">${Array.from({length:n},(_,i)=>`<i style="height:${9+Math.abs(Math.sin(i*2.31)*Math.cos(i*.21))*43}px"></i>`).join('')}</div>`;
const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div><div class="panel-body">${body}</div></section>`;
const navItems=[['production','⌂','Production'],['script','▤','Script'],['series','◧','Story Bible'],['booth','●','Booth'],['proof','≋','Proof'],['pickups','↶','Pickups'],['master','◉','Master & QC']];
function shell(body,active=screen){return `<div class="app-shell"><nav class="nav" aria-label="Main navigation"><div class="brand"><span class="logo">N</span><div>NARRATION<br><small>CONSOLE</small></div></div>${navItems.map(([id,icon,label],i)=>`${[0,1,3,4,6].includes(i)?`<div class="nav-group">${({0:'PRODUCTION',1:'PREP',3:'RECORD',4:'REVIEW',6:'FINISH'})[i]}</div>`:''}<a href="?screen=${id}" class="${active===id?'active':''}"><span class="nav-icon" aria-hidden="true">${icon}</span><span class="nav-label">${label}</span>${id==='proof'?'<span class="count">14</span>':''}</a>`).join('')}<div class="bottom"><a href="?screen=settings" class="${active==='settings'?'active':''}"><span aria-hidden="true">⚙</span><span class="nav-label">Settings</span></a></div></nav><div class="workspace"><header class="topbar">${btn('←','quiet','back')}<span class="eyebrow">PROJECT</span><span class="project">Alice’s Adventures in Wonderland</span><span class="spacer"></span><span class="chip good">● REAPER linked</span><span class="extra mono">100%</span></header><main>${body}</main></div></div>`}
const head=(title,sub,actions='')=>`<div class="page-head"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div><span class="spacer"></span><div class="actions">${actions}</div></div>`;
function production(){const chapters=['Opening credits','1 · Down the Rabbit-Hole','2 · The Pool of Tears','3 · A Caucus-Race','4 · The Rabbit Sends in a Little Bill','5 · Advice from a Caterpillar','6 · Pig and Pepper','7 · A Mad Tea-Party','8 · The Queen’s Croquet-Ground','9–12 · Four chapters','Closing credits'];const times=['0:12','11:48','12:05','10:31','13:10','12:40','13:22','~14 min','~15 min','~58 min','0:09'];return shell(`${head('Production','12 chapters · 29,198 words · Delivery due 14 Oct',btn('Export status','', 'export')+btn('Resume chapter 7','primary','resume'))}<div class="panel stats">${[['FINISHED AUDIO','1:52',' / 3:08','60% of estimated length'],['WORK TIME','11:20','','Recording, editing & proof'],['HOURS / FINISHED HOUR','6.1 : 1','','Based on logged time'],['EFFECTIVE RATE','$37',' / hr','At $225 PFH'],['OPEN PICKUPS','9','','Across 2 chapters'],['DELIVERY CHECK','7',' / 12','1 fail · 4 pending']].map(([l,v,u,s])=>`<div class="stat"><div class="eyebrow">${l}</div><div class="value">${v}<small>${u}</small></div><small>${s}</small>${l==='FINISHED AUDIO'?'<div class="bar"><i style="width:60%"></i></div>':''}</div>`).join('')}</div><div class="split"><section class="panel"><div class="panel-head"><h2>Chapter pipeline</h2><small>Open a cell to inspect its evidence</small><span class="spacer"></span>${btn('All chapters ▾','quiet','filter')}</div><div class="scroll-table"><table class="pipeline"><thead><tr>${['Chapter','Length','Prep','Record','Edit','Proof','Pickups','QC'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${chapters.map((c,i)=>`<tr class="${i===7?'selected':''}"><td style="text-align:left;max-width:240px">${c}</td><td class="mono">${times[i]}</td>${Array.from({length:6},(_,j)=>{let t='—',k='';if(i<3||j===0){t='✓';k='done'}if(i===3&&j===4){t='3 open';k='fail'}if(i===4&&j===5){t='Fail';k='fail'}if(i===5&&j===3){t='Proofer';k='wait'}if(i===5&&j===4){t='6 open';k='fail'}if(i===6&&j===2){t='62%';k='run'}if(i===7&&j===1){t='● 41%';k='run'}if(i===8&&j===0){t='2 queries';k='wait'}return `<td><span class="stage ${k}">${t}</span></td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="chart"><div class="row between"><span class="eyebrow">FINISHED HOURS VS PLAN</span><small>Actual — · Plan ···</small></div><svg viewBox="0 0 730 44"><path d="M0 37L730 5" fill="none" stroke="#9d9e91" stroke-dasharray="4 5"/><path d="M0 38L90 32L150 32L240 24L310 22L390 12L470 8" stroke="#ad551b" stroke-width="2" fill="none"/><circle cx="470" cy="8" r="4" fill="#ad551b"/></svg></div></section><div class="stack">${panel('Next up',`<div class="task"><span class="eyebrow">CURRENT SESSION</span><strong>Finish chapter 7</strong><p>Resume at paragraph 38. About 8 minutes of estimated finished audio remain.</p>${btn('Open Booth →','primary','resume')}</div><div class="task"><strong>9 pickup lines to record</strong><p>Chapters 3 and 5 · review the queue and original audio before recording.</p>${btn('Review pickups →','','pickups')}</div><div class="task"><strong>Chapter 4 needs a QC review</strong><p>Noise floor exceeds the selected profile. Open the measured evidence.</p>${btn('Inspect failed check →','','master')}</div>`)}${panel('Delivery outlook',`${badge('● On track','good')}<p style="margin:10px 0">At the current logged pace: <strong>9 Oct</strong></p><small>Estimate updates as finished audio and logged work change.</small><div class="divider"></div><div class="row between"><span>Booth hours this week</span><span class="mono">6 / 8 h</span></div><div class="bar"><i style="width:75%;background:var(--accent)"></i></div>`)}</div></div>`) }
function script(){return shell(`<div class="prep"><aside class="panel chapters"><div class="eyebrow" style="padding:8px">CHAPTERS · PREP</div>${['Opening credits','1 · Down the Rabbit-Hole','2 · The Pool of Tears','3 · A Caucus-Race','4 · The Rabbit Sends…','5 · Advice from a Caterpillar','6 · Pig and Pepper','7 · A Mad Tea-Party','8 · The Queen’s Croquet-Ground','9 · The Mock Turtle’s Story','10 · The Lobster Quadrille','11 · Who Stole the Tarts?','12 · Alice’s Evidence'].map((c,i)=>`<button class="${i===3?'active':''}" data-action="chapter">${c}${i===3?'<br><small>Selected · 1,694 words</small>':''}</button>`).join('')}<div class="divider"></div><small>Manual chapter navigation</small></aside><section class="panel reader"><div class="panel-head"><div><div class="eyebrow">SCRIPT · CHAPTER 3</div><h2>A Caucus-Race and a Long Tale</h2></div><span class="spacer"></span>${btn('Aa','quiet','textsize')}${btn('•••','quiet','more')}</div><div class="statusline row"><span>1,694 words · ~8 min read</span><span class="spacer"></span>${badge('4 to confirm','warn')}</div><div class="reader-copy"><p><span class="line-n">1</span><span class="speaker">NARRATOR</span>They were indeed a queer-looking party that assembled on the bank—the birds with draggled feathers, the animals with their fur clinging close to them, and all dripping wet, cross, and uncomfortable.</p><p><span class="line-n">2</span>The first question of course was, how to get dry again: they had a consultation about this, and after a few minutes it seemed quite natural to <span class="word">Alice</span> to find herself talking familiarly with them, as if she had known them all her life.</p><p><span class="line-n">3</span>Indeed, she had quite a long argument with the Lory, who at last turned sulky, and would only say, <mark>“I am older than you, and must know better”</mark>; and this Alice would not allow without knowing how old it was.</p><p><span class="line-n">4</span><span class="speaker blue">MOUSE</span>“Sit down, all of you, and listen to me!” said the Mouse. “I’ll soon make you dry enough!”</p></div><div class="reader-foot row"><small>Read-only manuscript · annotations are separate</small><span class="spacer"></span>${btn('Record in Booth','primary','resume')}</div></section><aside class="panel rail"><div class="tabs compact"><button class="active" data-tab="pronunciations">Pronunciations · 7</button><button data-tab="characters">Characters</button><button data-tab="queries">Queries</button></div><div id="rail-content"><table><thead><tr><th>Word / source</th><th>Say it</th><th></th></tr></thead><tbody>${[['Alice','AL-is'],['White Rabbit','White RAB-it'],['Queen of Hearts','Queen of HARTS'],['Hatter','HAT-er'],['Caterpillar','KAT-er-pil-er'],['Cheshire Cat','CHESH-er'],['Queen’s garden','—']].map(([w,p])=>`<tr><td><strong>${w}</strong><br><small>Researched</small></td><td class="mono">${p}</td><td>${btn('▷','quiet','audio')}</td></tr>`).join('')}</tbody></table><div class="panel-body"><small>Choose a word to review its pronunciation, source, and reference audio.</small></div></div><div class="panel-body" style="border-top:1px solid var(--rule)"><div class="eyebrow">SELECTED TEXT</div><h3 style="margin:8px 0">“I am older than you”</h3><p class="muted">Add an annotation while keeping the original text intact.</p><div class="actions" style="margin-top:16px">${btn('Add note','','note')}${btn('Mark stress','','stress')}</div></div></aside></div>`) }
function booth(){document.body.classList.add('dark');return `<div class="booth"><header class="booth-head">${badge('● READY','good')}<strong>Ch 1 · Down the Rabbit-Hole</strong><small>¶ 3 of 22</small><span class="spacer"></span><span class="eyebrow extra">INPUT</span><div class="meter"></div><span class="mono extra">−14.2 dB</span>${badge('REAPER linked','good')}${btn('Exit Booth','', 'production')}</header><div class="booth-content"><div class="booth-text"><div class="booth-line past"><span class="speaker">NARRATOR</span><p>Alice was beginning to get very tired of sitting by her sister on the bank, and of having nothing to do.</p></div><div class="booth-line past"><span class="speaker">NARRATOR</span><p>Once or twice she had peeped into the book her sister was reading, but it had no pictures or conversations in it.</p></div><div class="booth-line current"><span class="speaker">ALICE</span><p>“And what is the use of a book,” thought Alice, <mark>“without pictures or conversations?”</mark></p></div><div class="booth-line"><span class="speaker">NARRATOR</span><p>So she was considering in her own mind whether the pleasure of making a daisy-chain would be worth the trouble of getting up and picking the daisies.</p></div><div class="booth-line"><span class="speaker blue">WHITE RABBIT</span><p>“Oh dear! Oh dear! I shall be late!”</p></div></div><aside class="booth-rail"><div class="eyebrow">READING POSITION</div><h3 style="margin:8px 0">Start when you’re ready</h3><p class="muted">The reading cue follows your voice after you start following.</p><div class="divider"></div><div class="eyebrow">VOICES IN THIS CHAPTER</div><div class="task"><strong>Alice</strong><p>Curious · direct · youthful</p>${btn('▷ Reference','','audio')}</div><div class="task"><strong>White Rabbit</strong><p>Breathless · hurried</p>${btn('▷ Reference','','audio')}</div><div class="divider"></div><div class="eyebrow">COMING UP</div><p style="margin-top:9px">daisy-chain<br><span class="mono">DAY-zee chain</span></p><div class="divider"></div><small>Reference playback pauses following. All controls in this prototype are simulated.</small></aside></div><footer class="booth-foot">${btn('Start following','primary','follow')}<span><kbd>Space</kbd> Play / pause reading</span><span><kbd>F</kbd> Flag</span><span class="spacer"></span>${btn('Microphone ▾','','mic')}${btn('Reading settings','','reading')}</footer></div>`}
const findings=[['00:12.4','Misread','a White Rabbit with pink eyes','a white rabbit with pale eyes','Open'],['00:31.9','Skip','Oh dear!','Not heard','Open'],['—','Story Bible','White Rabbit','Review reference','Open'],['00:08.2','Extra words','Not in script','and then','Waived']];
function proof(){return shell(`${head('Proof','All chapters · Review evidence and decide what needs attention',btn('Import proofer sheet','','import')+btn('Export for proofer','','export'))}<div class="split"><section class="panel"><div class="panel-head"><h2>Notes</h2>${badge('4 total')}${badge('3 to review','warn')}<span class="spacer"></span>${btn('Review shortcuts','quiet','shortcuts')}</div><div class="toolbar"><input id="finding-search" class="search" placeholder="Find in notes…" aria-label="Search findings"><span class="spacer"></span>${btn('Chapter: all ▾','','filter')}${btn('Open + deferred ▾','','filter')}</div><div class="statusline">Choose a note to hear the evidence and review its resolution.</div><table><thead><tr><th>Time / chapter</th><th>Type</th><th>Script → heard</th><th>Resolution</th></tr></thead><tbody id="findings-body">${findings.map((f,i)=>`<tr class="clickable ${i===0?'selected':''}" data-finding="${i}" tabindex="0"><td class="mono">${f[0]}<br><small>Chapter 1</small></td><td>${badge(f[1],['Misread','Skip','Repeat'].includes(f[1])?'bad':'blue')}</td><td>${f[2]}<br><small>${f[3]}</small></td><td>${badge(f[4],f[4]==='Pickup'?'bad':'')}</td></tr>`).join('')}</tbody></table><div id="no-results" class="empty hidden"><h2>No notes match</h2><p>Your review decisions are still saved. Try another search or clear the filters.</p>${btn('Clear filters','','clear')}</div><div class="transport">${btn('▶','','audio')}${wave(95)}<span class="mono">00:08.4</span></div><div class="panel-body"><small>Evidence from the latest saved check. Decisions are retained across checks.</small></div></section><aside class="stack"><section class="panel inspector"><div class="panel-head"><div><div class="eyebrow">SELECTED NOTE</div><h2 id="finding-title">00:12.4 · Misread</h2></div><span class="spacer"></span>${btn('↑','quiet','previous')}${btn('↓','quiet','next')}</div><div class="panel-body"><div class="row between">${badge('Current evidence','good')}<span class="mono" id="finding-position">1 of 4</span></div><div class="divider"></div><div class="eyebrow">SCRIPT · CHAPTER 1</div><p class="excerpt" id="script-evidence">…when suddenly a White Rabbit with <mark>pink eyes</mark> ran close by her.</p><div class="eyebrow">HEARD</div><p class="excerpt" id="heard-evidence">“…when suddenly a white rabbit with <mark>pale eyes</mark> ran close by her.”</p><div class="actions">${btn('▶ Play ±3 s','','audio')}${btn('Go to REAPER','','daw')}</div><div class="divider"></div><label class="form-label" for="review-note">Review note <small>optional</small></label><textarea id="review-note" placeholder="Context for the pickup or edit…"></textarea><div class="eyebrow" style="margin:15px 0 9px">RESOLUTION</div><div class="decision">${btn('Needs pickup','primary','decide')}${btn('Fix in edit','','decide')}${btn('Waive','','decide')}${btn('Defer','','decide')}</div><div class="mock-note">Proposed addition: previous / next controls in the overview inspector, plus immediate Undo. Current app already has decisions and Reopen.</div></div></section>${panel('After review',`<p>Pickups remain visible in the recording queue. Waived and deferred notes stay available in the resolution filter.</p><div class="divider"></div>${btn('Open pickup queue →','','pickups')}`)}</aside></div>`) }
function master(){const rows=[['00 Opening credits','0:12','−20.1','−3.4','−64.8','Pass'],['01 Down the Rabbit-Hole','11:48','−19.6','−3.2','−63.9','Pass'],['02 The Pool of Tears','12:05','−19.9','−3.1','−64.2','Pass'],['03 A Caucus-Race','10:31','—','—','—','Pending'],['04 The Rabbit Sends…','13:10','−20.4','−3.6','−57.8','Fail'],['Retail sample','4:40','−19.8','−3.3','−64.0','Pass']];return shell(`${head('Master & QC','Measurements belong to the selected files and saved profile.',btn('Profile: ACX ▾','','profile')+btn('Re-check files','primary','measure'))}<div class="split"><div class="stack"><section class="panel"><div class="panel-head"><h2>Per-file checks</h2><span class="spacer"></span>${badge('1 failed check','bad')}</div><table><thead><tr>${['File','Length','RMS','True peak','Noise floor','Result'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i===4?'selected':''}">${r.map((v,j)=>`<td class="${j>0&&j<5?'mono':''}">${j===5?badge(v,v==='Fail'?'bad':v==='Pass'?'good':''):v}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="panel-body"><small>Illustrative measurement data · this prototype does not validate delivery specifications.</small></div></section>${panel('04 · Why it fails',`<div class="row between"><strong>Noise floor exceeds this profile</strong>${badge('Needs review','bad')}</div><div class="two-col" style="margin-top:18px"><div><div class="eyebrow">MEASURED</div><div class="value" style="color:var(--red)">−57.8 <small>dB</small></div></div><div><div class="eyebrow">PROFILE LIMIT</div><div class="value">≤ −60 <small>dB</small></div></div></div><p class="muted">Listen to the measured segment before choosing an edit. A changed render must be measured again.</p><div class="actions" style="margin-top:16px">${btn('▶ Quietest segment','','audio')}${btn('Open in REAPER','','daw')}</div>`)}${panel('Mastering chain',`<div class="row" style="flex-wrap:wrap">${['Room tone','De-click','High-pass','EQ','Limiter','Gain'].map((x,i)=>`${i?'<span class="muted">→</span>':''}${badge(x)}`).join('')}</div><div class="divider"></div><div class="row">${btn('Edit chain','','chain')}${btn('A/B raw and mastered','','audio')}<span class="spacer"></span><small>Changes require a new render and check.</small></div>`)}</div><aside class="panel"><div class="panel-head"><h2>Delivery readiness</h2></div><div class="panel-body"><div class="eyebrow">PACKAGE · ACX</div><div class="task"><strong>✓ Opening & closing credits</strong><p>Separate files included.</p></div><div class="task"><strong>✓ Chapter naming</strong><p>One file for each chapter.</p></div><div class="task"><strong style="color:var(--red)">× Chapter 4 noise floor</strong><p>Review and re-check this file.</p></div><div class="task"><strong>◷ 4 chapters pending</strong><p>Files have not been measured yet.</p></div><div class="divider"></div><p class="muted">Resolve the failed check and pending measurements before building this package.</p><div class="actions" style="margin-top:16px"><button class="primary" disabled>Build package</button>${btn('Preview naming','','naming')}</div><div class="divider"></div>${btn('Export QC report','','export')}<p class="footer-note">Package readiness and audio processing are separate steps.</p></div></aside></div>`) }
function series(){return shell(`${head('Story Bible','Wonderland series · 2 books',btn('Book entries','','entries')+btn('Series voices','primary','series'))}<div class="split" style="grid-template-columns:265px minmax(0,1fr)"><aside class="panel"><div class="panel-head"><h2>Series voices</h2></div><div class="panel-body"><input class="search" style="width:100%" placeholder="Find a character…" aria-label="Find a character"></div>${['Alice','Hatter','March Hare','Queen of Hearts','Dormouse','Cheshire Cat','White Rabbit'].map((x,i)=>`<div class="list-item ${i===1?'active':''}"><span class="avatar">${x.slice(0,2).toUpperCase()}</span><div><strong>${x}</strong><br><small>${i===4?'No reference yet':'Books 1, 2'}</small></div></div>`).join('')}</aside><div class="stack"><div class="row"><div><h1>Hatter</h1><p class="muted">HAT-er · Author-confirmed pronunciation</p></div><span class="spacer"></span>${btn('Approve reference','primary','approve')}</div><div class="two-col">${panel('Reference clips',`${[['Book 1 · Ch 7','Your hair wants cutting.','Anchor'],['Book 1 · Ch 11','I’m a poor man…','Approved'],['Book 2 · Ch 5','It’s always six o’clock now.','Candidate']].map(([a,b,c])=>`<div class="task row">${btn('▷','','audio')}<div><strong>${a}</strong><small>“${b}”</small></div><span class="spacer"></span>${badge(c,c==='Anchor'?'accent':'')}</div>`).join('')}`)}${panel('Voice notes',`<p><strong>Character</strong><br>Quick changes between offence and glee. Upper-middle London, slightly nasal, forward placement.</p><div class="divider"></div><p><strong>Author direction</strong><br>“Not a cockney—think a shabby gentleman.”</p><small>Recorded source · email, 12 Sep</small>`)}</div>${panel('Candidate against approved references',`<small>Measured evidence for your judgment. This is not a verdict on the performance.</small><div class="metric-list">${[['Median pitch','184 Hz · references 168–172'],['Speaking rate','3.9 syllables/s · references 3.8–4.1'],['Brightness','Within reference range']].map(([a,b])=>`<div><div class="row between"><strong>${a}</strong><span class="mono">${b}</span></div><div class="range" style="--point:${a==='Median pitch'?67:a==='Speaking rate'?55:48}%"></div></div>`).join('')}</div><div class="row" style="margin-top:15px">${badge('Pitch above selected references','warn')}<span class="spacer"></span>${btn('A/B with anchor','','audio')}</div>`)}<div class="notice">Candidate stays unapproved until you choose it. Existing approved clips remain available.</div></div></div>`,'series')}
function companion(){document.body.classList.add('dark');return `<div class="companion"><div class="transport"><span class="logo">N</span><strong>Companion</strong><span class="spacer"></span>${btn('Full app ↗','quiet','production')}</div><section><div class="row between"><span class="eyebrow">CHAPTER 1 · ¶ 3</span>${badge('Paused','warn')}</div><p style="margin-top:13px">Alice was beginning to get very tired of sitting by her sister on the bank, and of having <mark>nothing to do</mark>.</p><small>Reading position is retained.</small></section><section><div class="row between"><span class="eyebrow">NOTE AT POSITION</span>${badge('Open','bad')}</div><h2 style="margin:10px 0">00:08.4 · Misread</h2><p class="mini">Script says “nothing to do.”<br>Heard “nothing to say.”</p><div class="actions" style="margin-top:14px">${btn('▶ Play ±3 s','','audio')}${btn('Open Proof','','proof')}</div><div class="divider"></div><div class="decision">${btn('Needs pickup','primary','decide')}${btn('Waive','','decide')}</div></section><section><div class="eyebrow">PICKUPS · THIS CHAPTER</div>${[['00:21.7','pictures or conversations'],['01:18.5','she ran'],['02:01.1','waistcoat-pocket']].map(([t,s])=>`<div class="list-item"><span class="mono">${t}</span><span>${s}</span></div>`).join('')}</section><section style="margin-top:auto"><div class="row">${badge('● REAPER linked','good')}<span class="spacer"></span><small>Window focused</small></div><p class="mini muted" style="margin-top:12px">Reading shortcuts work while this window has focus. REAPER key forwarding is not available.</p></section><div class="transport">${btn('Start following','primary','follow')}<span class="spacer"></span>${btn('⚙ Settings','quiet','settings')}</div></div>`}
function settings(){return shell(`${head('Settings','Preferences have a clear scope; project overrides stay visible.',btn('Global','','scope')+btn('This project','primary','scope'))}<div class="settings-grid"><nav class="category" aria-label="Settings categories">${['General','Appearance','Manuscript','Booth','Keyboard & pedals','Proof','Story Bible','Delivery','DAW Integration','Local assets','About & updates'].map(x=>`<button class="${x==='Booth'?'active':''}" data-action="category">${x}</button>`).join('')}</nav><div class="stack"><section class="panel"><div class="panel-head"><h2>Booth</h2><span class="spacer"></span>${badge('This project')}</div><div class="panel-body"><p class="muted">Make the reading view comfortable for this book.</p><div class="fieldrow"><div><strong>Reader text size</strong><p>Controls the manuscript text while reading in the Booth.</p><small style="color:var(--accent)">Project override · global: Medium</small></div><select aria-label="Reader text size"><option>Large</option><option>Medium</option><option>Small</option></select></div><div class="fieldrow"><div><strong>Reader theme</strong><p>Use a separate appearance for the Booth.</p><small>Inherited from global settings</small></div><select aria-label="Reader theme"><option>Dark</option><option>Light</option></select></div><div class="fieldrow"><div><strong>Show speaker tags</strong><p>Display reviewed speaker labels beside dialogue.</p><small>Inherited from global settings</small></div><button role="switch" aria-checked="true" aria-label="Show speaker tags" class="quiet" data-action="toggle"><span class="toggle"></span></button></div><div class="fieldrow"><div><strong>Restore global value</strong><p>Remove this project’s text-size override.</p></div>${btn('Use global value','','reset')}</div></div><div class="savebar"><span>1 unsaved change</span><span class="spacer"></span>${btn('Discard','','discard')}${btn('Save changes','primary','save')}</div></section>${panel('Keyboard & pedals',`<div class="row"><div><p>Reading commands have their own scope.</p><small>Review bindings and conflicts before recording.</small></div><span class="spacer"></span>${btn('Manage bindings →','','keyboard')}</div>`)}<small>Proposed layout uses existing scope, inheritance, Save/Discard, and navigation protection behaviors.</small></div></div>`,'settings')}
function importScreen(){return shell(`${head('Production','Prepare the manuscript before recording.')}${panel('Manuscript','Review a new manuscript before importing it.')}`,'production')+`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="import-heading"><div class="dialog-head row"><div><div class="eyebrow">IMPORT MANUSCRIPT · REVIEW</div><h1 id="import-heading">Check the chapter outline</h1><p class="muted" style="margin-top:7px">alice-in-wonderland.docx · Source copy will be retained</p></div><span class="spacer"></span>${btn('Cancel','','production')}</div><div class="dialog-main"><div class="row">${badge('12 chapters','good')}${badge('29,198 words')}${badge('6 character suggestions')}${badge('1 item needs review','warn')}</div><div class="two-col" style="margin-top:18px;grid-template-columns:1fr 1.15fr"><section class="panel"><div class="panel-head"><h2>Chapter outline</h2></div><table><thead><tr><th>Detected heading</th><th>Words</th></tr></thead><tbody>${[['Opening pages','143'],['Chapter 1 · Down the Rabbit-Hole','2,140'],['Chapter 2 · The Pool of Tears','2,093'],['Chapter 3 · A Caucus-Race','1,694'],['Chapter 4 · The Rabbit Sends…','2,618'],['Chapter 5 · Advice from a Caterpillar','2,172']].map(([a,b],i)=>`<tr class="${i===3?'selected':''}"><td>${a}</td><td class="mono">${b}</td></tr>`).join('')}</tbody></table><div class="panel-body"><small>6 more chapters below</small></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>Selected chapter preview</h2></div><div class="panel-body"><h3>Chapter 3 · A Caucus-Race and a Long Tale</h3><p style="font-size:16px;line-height:1.8;margin-top:14px">They were indeed a queer-looking party that assembled on the bank—the birds with draggled feathers, the animals with their fur clinging close to them…</p></div></section><div class="notice"><strong>Subtitle detected</strong><p style="margin-top:5px">“And a Long Tale” is part of this heading. Keep it with the chapter title?</p><label style="display:block;margin-top:10px"><input type="checkbox" checked> Keep detected subtitle</label></div><label><input type="checkbox" checked> Review character suggestions after import</label><small>Suggestions remain unconfirmed until reviewed.</small></div></div></div><div class="dialog-foot"><small>Import creates the project’s read-only manuscript.</small><span class="spacer"></span>${btn('Back to file selection','','back')}${btn('Import reviewed manuscript','primary','import-commit')}</div></section></div>`}
function pickups(){return shell(`${head('Pickups','9 lines · Chapters 3 and 5 · Review original context before recording',btn('Import CSV','','import')+btn('Export script','','export'))}<div class="split"><section class="panel"><div class="panel-head"><h2>Pickup queue</h2><span class="spacer"></span>${badge('Proposed session view','accent')}</div><div class="toolbar">${btn('Remaining · 9','','filter')}${btn('Done · 0','quiet','filter')}<span class="spacer"></span><small>Ordered by chapter and time</small></div><table><thead><tr><th>Chapter / time</th><th>Line and reason</th><th>Status</th></tr></thead><tbody>${[['3','02:14.6','“Who are you?”','Stress is on “you”'],['3','03:40.2','“I can’t explain myself…”','Skipped word'],['3','05:31.0','“hookah”','Pronunciation'],['5','01:12.8','“and she went on”','Repeated word'],['5','02:21.3','“curiouser and curiouser”','Misread'],['5','03:18.5','“the serpent”','Chair noise']].map((r,i)=>`<tr class="clickable ${i===0?'selected':''}" data-action="pickup-row"><td>Chapter ${r[0]}<br><span class="mono">${r[1]}</span></td><td><strong>${r[2]}</strong><br><small>${r[3]}</small></td><td>${badge('To record','bad')}</td></tr>`).join('')}</tbody></table><div class="panel-body"><small>3 more lines in Chapter 5</small></div></section><aside class="stack">${panel('Selected pickup',`<div class="eyebrow">CHAPTER 3 · 02:14.6</div><p style="font-size:19px;margin:16px 0">“Who are <em>you</em>?” said the Caterpillar.</p><p class="muted">Stress “you” as written. Keep the surrounding sentence in view.</p><div class="divider"></div><div class="actions">${btn('▶ Original context','','audio')}${btn('Open Proof','','proof')}</div><div class="divider"></div><div class="eyebrow">RECORDING READINESS</div><p style="margin:8px 0">● REAPER linked</p><p class="muted">Punch is available only when supported and enabled for this project.</p><div class="actions" style="margin-top:16px">${btn('Open in Booth','primary','resume')}</div><div class="divider"></div>${btn('Mark pickup done','','done')}`)}<div class="notice">The current app has sequential Next pickup and Mark done. This selectable session queue is a proposed capability.</div></aside></div>`,'pickups')}
function project(){return `<div class="project-screen"><div class="project-card"><div class="brand"><span class="logo">N</span><div>NARRATION<br><small>CONSOLE</small></div></div><div class="project-intro"><div><h1>Choose your project</h1><p>Open the book you’re working on, or start a new project.</p></div>${btn('New project','primary','create')}</div><section class="panel"><div class="panel-head"><h2>Recent projects</h2><span class="spacer"></span>${btn('Browse folders…','','browse')}</div>${[['Alice’s Adventures in Wonderland','C:\\Audiobooks\\Alice','Today'],['Through the Looking-Glass','C:\\Audiobooks\\Looking-Glass','23 Sep'],['The Secret Garden','C:\\Audiobooks\\Secret Garden','18 Sep']].map(([a,b,c])=>`<div class="list-item"><span class="avatar">▤</span><div><strong>${a}</strong><br><small class="mono">${b}</small></div><span class="spacer"></span><small>${c}</small>${btn('Open →','','production')}${btn('•••','quiet','recent')}</div>`).join('')}</section><div class="row" style="margin-top:20px"><small>Project files stay in the folder you choose.</small><span class="spacer"></span>${btn('Settings','quiet','settings')}</div><p class="mock-note">Illustrative recent-project list. The existing picker already supports browse, create, recents, and error feedback.</p></div></div>`}
function states(){return shell(`${head('Proof · interaction states','Extension of the benchmark language to everyday interruptions and recovery.')}<div class="state-grid">${panel('No matching notes',`<p>Your search “unicorn” has no matches.</p><p class="muted" style="margin:8px 0 18px">Existing notes and decisions are unchanged.</p>${btn('Clear filters','','clear')}`)}${panel('Comparison in progress',`<div class="row between"><strong>Comparing chapter 4 of 12</strong><span class="mono">4 / 12</span></div><div class="bar" style="height:7px;margin:18px 0"><i style="width:33%"></i></div><small>Illustrative host-reported work units; no estimated completion time.</small><div class="actions" style="margin-top:15px">${btn('Continue in background','','background')}${btn('Cancel comparison','','cancel-job')}`)}${panel('Audio could not be loaded',`<div class="notice"><strong>The selected audio file is unavailable.</strong><p style="margin-top:6px">Your input choices and review note are retained.</p></div><div class="actions" style="margin-top:15px">${btn('Choose file','primary','browse')}${btn('Retry','','retry')}${btn('Details','quiet','details')}`)}${panel('Evidence changed',`<p>This note is based on an earlier recording check.</p><p class="muted" style="margin:8px 0 18px">We kept your typed review note. Inspect the latest evidence before applying the decision.</p>${btn('Review latest evidence','primary','proof')}`)}${panel('REAPER is not connected',`<p>You can continue reviewing notes here.</p><p class="muted" style="margin:8px 0 18px">Go to REAPER and marker actions become available after reconnecting.</p>${btn('Open DAW settings','','settings')}`)}${panel('Decision saved',`<div class="notice" style="background:var(--greenbg);border-color:#b7cbb4;color:var(--green)"><strong>Marked as pickup.</strong> 8 open notes remain.</div><div class="actions" style="margin-top:15px">${btn('Undo','','undo')}${btn('Next note →','primary','proof')}</div><small style="display:block;margin-top:12px">Immediate Undo is proposed; current app already offers Reopen.</small>`)}</div><p class="footer-note">These are state studies, not simultaneous messages. Existing app behavior is retained unless labeled as proposed.</p>`,'proof')}
const renderers={production,script,booth,proof,master,series,companion,settings,import:importScreen,pickups,project,states};
app.innerHTML=(renderers[screen]||production)()+`<div class="prototype-stamp">PROPOSED · ILLUSTRATIVE DATA · 29 SEP 2026</div>`;
let selected=0;
function toast(t){const el=document.querySelector('#toast');el.innerHTML=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',5000)}
function pickFinding(i){selected=(i+findings.length)%findings.length;document.querySelectorAll('[data-finding]').forEach(e=>e.classList.toggle('selected',Number(e.dataset.finding)===selected));const f=findings[selected];document.querySelector('#finding-title').textContent=f[0]+' · '+f[1];document.querySelector('#finding-position').textContent=(selected+1)+' of '+findings.length;document.querySelector('#script-evidence').textContent=f[2];document.querySelector('#heard-evidence').textContent=f[3]}
document.addEventListener('click',e=>{const finding=e.target.closest('[data-finding]');if(finding){pickFinding(Number(finding.dataset.finding));return}const tab=e.target.closest('[data-tab]');if(tab){document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===tab));if(tab.dataset.tab!=='pronunciations')document.querySelector('#rail-content').innerHTML=`<div class="panel-body"><h3>${tab.dataset.tab==='queries'?'13 queries to review':'6 reviewed characters'}</h3><p class="muted" style="margin-top:14px">${tab.dataset.tab==='queries'?'Review unresolved pronunciation questions and their sources.':'Alice · White Rabbit · Hatter · Caterpillar · Cheshire Cat · Queen of Hearts'}</p></div>`;else location.reload();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(renderers[a]){location.search='?screen='+a;return}if(a==='resume'){location.search='?screen=booth';return}if(a==='next'||a==='previous'){pickFinding(selected+(a==='next'?1:-1));return}if(a==='clear'){const s=document.querySelector('#finding-search');if(s){s.value='';s.dispatchEvent(new Event('input'))}else toast('Filters cleared · prototype');return}if(a==='decide'){toast(`${b.textContent} saved in prototype. <button data-action="undo">Undo</button>`);return}if(a==='undo'){toast('Decision restored · prototype');return}if(a==='save'||a==='discard'){const bar=document.querySelector('.savebar');if(bar)bar.innerHTML=`<span>${a==='save'?'Changes saved for this project.':'Changes discarded.'}</span>`;toast(a==='save'?'Project preferences saved · prototype':'Changes discarded · prototype');return}if(a==='toggle'){const v=b.getAttribute('aria-checked')==='true';b.setAttribute('aria-checked',String(!v));b.style.opacity=v?'.5':'1';return}if(a==='follow'){b.textContent=b.textContent.includes('Start')?'Pause following':'Start following';toast('Reading cue toggled · simulated, no microphone used');return}if(a==='audio'){toast('Audio control demonstration · no audio fixture attached');return}if(a==='import-commit'){toast('Import preview complete · no project data changed');return}if(a==='done'){b.textContent='Marked done ✓';toast('Pickup marked done in prototype');return}if(a==='back'){history.back();return}if(a==='textsize'){const t=document.querySelector('.reader-copy');t.style.fontSize=t.style.fontSize==='20px'?'17px':'20px';return}toast(`${b.textContent.trim()} · visual prototype only`)});
document.querySelector('#finding-search')?.addEventListener('input',e=>{let n=0;document.querySelectorAll('[data-finding]').forEach(r=>{const yes=r.textContent.toLowerCase().includes(e.target.value.toLowerCase());r.classList.toggle('hidden',!yes);n+=yes?1:0});document.querySelector('#no-results').classList.toggle('hidden',n!==0)});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.target.matches('[data-finding]')&&e.key==='Enter')pickFinding(Number(e.target.dataset.finding));if(e.key==='Escape')document.querySelector('#toast').style.display='none'});
// Keep the overview mock's fixed fixture labels consistent with its four notes.
if(screen==='proof'){
  document.querySelector('.nav .count').textContent='4';
  document.querySelector('.transport .mono').textContent='00:12.4';
  document.querySelector('[data-finding="3"] td small').textContent='Chapter 2';
  const filters=[...document.querySelectorAll('[data-action="filter"]')];
  filters.at(-1).textContent='All resolutions ▾';
}
